/// `amdgpu.permlane_swap`: AMDGPU permlane swap op
///
/// High-level wrapper on `rocdl.permlane{16,32}.swap` variants for permutations
/// on rows of lanes in a subgroup.
///
/// Supports arbitrary int/float/vector types, which will be repacked to i32 and
/// one or more `rocdl.permlane_swap` ops during lowering.
/// Supported lane permutations:
/// - Swap the data between odd and even rows of 16 lanes
/// - Swap the data between the first 32 lanes and the last 32 lanes
///
/// Example:
/// ```mlir
/// %0 = amdgpu.permlane_swap %src 16 : f16
/// %1 = amdgpu.permlane_swap %src 32 { fetch_inactive = true, bound_ctrl = true } : f16
/// ```
///
/// Operands:
/// * `$src`: Vector register to permute across lanes of the subgroup.
/// * `$row_length`: The length of a row to permute in number of lanes (valid values are 16 and 32).
/// * `$fetch_inactive`: Optional. Used to dertermine behavior of a fetch from a disabled lane.
///   `fetch_inactive = false`: If the source lane is disabled, use `bound_ctrl` to determine the source value.
///   `fetch_inactive = true`: If the source lane is disabled, fetch the source value anyway (ignoring `bound_ctrl`).
/// * `$bound_ctrl`: Optional. Used to determine what a thread should do if its source operand is from
///   a disabled lane: use the value zero, or disable the write.
///   `bound_ctrl = false`: Do not write when source is from a disabled lane
///   `bound_ctrl = true`: Use zero as input if source is from a disabled lane
///
/// Note: Lowering is only supported on gfx950 and up.
#[mlir::op("amdgpu.permlane_swap", format = "$src $row_length attr-dict `:` type($result)", results(result))]
pub struct PermlaneSwapOp<'a> {
    #[slot(result)]
    pub src: Value<'a>,
    #[attr(int = "i32")]
    pub row_length: Attribute<'a>,
    #[attr(default = "false")]
    pub fetch_inactive: Option<Attribute<'a>>,
    #[attr(default = "false")]
    pub bound_ctrl: Option<Attribute<'a>>,
    pub result: Type<'a>,
}

/// `amdgpu.permlane_var`: AMDGPU variable-selector permlane op (GFX12+)
///
/// High-level wrapper on `rocdl.permlane16.var` and `rocdl.permlanex16.var`
/// for per-lane variable-selector permutations within a wave32 subgroup.
///
/// Supports arbitrary int/float/vector types, which will be repacked to i32
/// and one or more ROCDL intrinsic calls during lowering.
///
/// - `cross = false`: intra-row permutation (each lane in a 16-lane row reads
///   from a lane in the same row, selected by `$selector`). Maps to
///   `rocdl.permlane16.var`.
/// - `cross = true`: cross-row permutation (each lane reads from the opposite
///   16-lane row, selected by `$selector`). Maps to `rocdl.permlanex16.var`.
///
/// `$selector` is an i32 VGPR providing the per-lane source-lane index.
///
/// Example:
/// ```mlir
/// %0 = amdgpu.permlane_var %src, %sel { cross = false } : f16
/// %1 = amdgpu.permlane_var %src, %sel { cross = true } : f32
/// ```
///
/// Note: Lowering is only supported on GFX12+.
#[mlir::op("amdgpu.permlane_var", format = "$src `,` $selector attr-dict `:` type($result)", results(result))]
pub struct PermlaneVarOp<'a> {
    #[slot(result)]
    pub src: Value<'a>,
    #[slot(selector_ty)]
    pub selector: Value<'a>,
    #[attr(default = "false")]
    pub cross: Option<Attribute<'a>>,
    #[attr(default = "false")]
    pub fetch_inactive: Option<Attribute<'a>>,
    #[attr(default = "false")]
    pub bound_ctrl: Option<Attribute<'a>>,
    #[dtype(is = i32)]
    pub selector_ty: Type<'a>,
    pub result: Type<'a>,
}

