/// `amdgpu.transpose_load`: MLIR wrapper for CDNA transpose Load instructions
///
/// The `amdgpu.transpose_load` op is a wrapper around the `ds_read_tr` instructions
/// on gfx9 and the `ds_load_tr` family of instructions on gfx1250.
///
/// The transpose load op represents a subgroup load from LDS memory,
/// where the subgroup of threads collectively reads a matrix from the source
/// memref, with each thread reading a vector of the matrix, and gets a transposed matrix
/// in as the result. That is, each thread reads a vector of the col-major matrix at different
/// indices, and the thread's read result is a vector of the corresponding row of the transposed
/// matrix.
///
/// This op is a direct wrapper around the ROCDL `ds_read_tr` family intrinsics on
/// gfx950 and the `ds_load_tr` family of instructions on gfx1250. Please refer
/// to the respective ISA documentation for more details about its exact semantics.
///
/// Format example:
/// ```text
/// %0 = amdgpu.transpose_load %src[%srcIndices] : memref<128x256xf16> -> vector<4xf16>
/// ```
/// Operands:
/// * `$src`: LDS memref to read from.
/// * `$srcIndices`: indices into `$src` to read from for this thread. Indices
///   must be non-negative and in-bounds for the corresponding dimension of
///   `$src`, matching the constraints of `memref.load`.
/// * `$result`: target register this transpose load instruction will write to.
///
/// Note: Lowering is only supported on gfx950 and gfx1250, with different
/// permitted load types.
#[mlir::op("amdgpu.transpose_load", format = "$src `[` $srcIndices `]` attr-dict `:` type($src) `->` type($result)", results(result))]
pub struct TransposeLoadOp<'a> {
    #[slot(src_ty)]
    pub src: Value<'a>,
    #[slot(src_indices_ty, name = "srcIndices")]
    pub src_indices: Vec<Value<'a>>,
    pub src_ty: Type<'a>,
    #[dtype(is = index)]
    pub src_indices_ty: Type<'a>,
    pub result: Type<'a>,
}

/// `amdgpu.wmma`: MLIR wrapper for wmma instructions
///
/// The `amdgpu.wmma` op is an MLIR wrapper around intrinsics for various `wmma`
/// instructions in the AMDGPU architecture, which perform matrix multiplication.
///
/// On gfx11/RDNA3, wmma intrinsics have M=N=K=16 dimensions.
///
/// On gfx12/RDNA4, wmma intrinsics have M=N=16 dimensions and support K=16 for
/// all element types, and K=32 for i4 sources.
///
/// On gfx1250, wmma intrinsics have M=N=16 and K dimensions of 4, 32, 64, or 128,
/// depending on the element types.
///
/// On gfx11/RDNA3, emitting f16->f16 (or bf16->bf16) wmma the output is a 16xf16
/// (or 16xbf16) vector containing only 8 valid values:
///   - If `subwordOffset` is 0, then the output is stored at indices 0, 2, 4, ..., 14.
///   - If `subwordOffset` is 1, then the output is stored at indices 1, 3, 5, ..., 15.
/// On gfx12/RDNA4 and gfx1250, the result is instead returned as vector where all
/// the values are valid and the `subwordOffset` must be `0`, as it cannot be used.
///
/// `unsignedA` and `unsignedB` flag that the `int8` LLVM inputs are unsigned.
///
/// The `clamp` flag is used to saturate the output of type T to `numeric_limits<T>::max()`
/// in case of overflow.
///
/// The `wave64`attribute indicates whether an op is designed for 64 threads wavefont.
///
/// Example:
/// ```mlir
///   %0 = amdgpu.wmma 16x16x16 %matA * %matB + %matC : vector<8xf16>, vector<8xf16>, vector<8xf16>
///
///   %1 = amdgpu.wmma 16x16x64 %matD * %matE + %matF : vector<32xi8>, vector<8xf32>, vector<8xf32>
///
///   %2 = amdgpu.wmma 16x16x128 %matG * %matH + %matI : vector<64xf4E2M1FN>, vector<64xf4E2M1FN>, vector<8xf32>
///
///   %3 = amdgpu.wmma 16x16x4 %matJ * %matK + %matL : vector<2xf32>, vector<2xf32>, vector<8xf32>
/// ```
///
/// Generic form only (directive `custom<MNKDimensionList>`).
#[mlir::op("amdgpu.wmma", results(dest_d))]
pub struct WMMAOp<'a> {
    #[slot(source_a_ty, name = "sourceA")]
    pub source_a: Value<'a>,
    #[slot(source_b_ty, name = "sourceB")]
    pub source_b: Value<'a>,
    #[slot(dest_d, name = "destC")]
    pub dest_c: Value<'a>,
    #[attr(int = "i32")]
    pub m: Attribute<'a>,
    #[attr(int = "i32")]
    pub n: Attribute<'a>,
    #[attr(int = "i32")]
    pub k: Attribute<'a>,
    #[attr(name = "subwordOffset", int = "i32", default = "0")]
    pub subword_offset: Option<Attribute<'a>>,
    #[attr(name = "unsignedA")]
    pub unsigned_a: bool,
    #[attr(name = "unsignedB")]
    pub unsigned_b: bool,
    pub clamp: bool,
    pub source_a_ty: Type<'a>,
    pub source_b_ty: Type<'a>,
    pub dest_d: Type<'a>,
}

/// The `amdgpu` dialect.
#[mlir::dialect(
    "amdgpu",
    ops = [DPPOp, DotOp, DsAsyncBarrierArriveOp, DsBarrierArriveOp, DsBarrierInitOp, DsBarrierPollStateOp, DsBarrierStateInitCountOp, DsBarrierStatePendingCountOp, DsBarrierStatePhaseOp, DsBarrierStatePhaseParity, ExtPackedFp8Op, FatRawBufferCastOp, GatherToLDSOp, GlobalLoadAsyncToLDSOp, GlobalPrefetchOp, GlobalTransposeLoadOp, LDSBarrierOp, MFMAOp, MakeDmaBaseOp, MakeDmaDescriptorOp, MakeGatherDmaBaseOp, MakeGatherDmaDescriptorOp, MemoryCounterWaitOp, PackedScaledTruncOp, PackedStochRoundFp8Op, PackedTrunc2xFp8Op, PermlaneSwapOp, PermlaneVarOp, RawBufferAtomicCmpswapOp, RawBufferAtomicFaddOp, RawBufferAtomicFmaxOp, RawBufferAtomicSmaxOp, RawBufferAtomicUminOp, RawBufferLoadOp, RawBufferStoreOp, ScaledExtPackedMatrixOp, ScaledExtPackedOp, ScaledMFMAOp, ScaledWMMAOp, SchedBarrierOp, SparseMFMAOp, SparseWMMAOp, SwizzleBitModeOp, TensorLoadToLDSOp, TensorStoreFromLDSOp, TransposeLoadOp, WMMAOp],
    dependents = ["rocdl", "arith", "gpu"]
)]
pub struct AmdgpuDialect;
